require "test_helper"

# Generated by maquina:oauth.
class OauthDiscoveryTest < ActionDispatch::IntegrationTest
  test "publishes the authorization server metadata" do
    get oauth_authorization_server_path

    assert_response :success
    body = response.parsed_body
    assert_equal "http://www.example.com", body["issuer"]
    assert_equal "http://www.example.com/oauth/authorize", body["authorization_endpoint"]
    assert_equal "http://www.example.com/oauth/token", body["token_endpoint"]
    assert_equal "http://www.example.com/oauth/revoke", body["revocation_endpoint"]
    assert_equal ["code"], body["response_types_supported"]
    assert_equal ["authorization_code", "refresh_token"], body["grant_types_supported"]
    assert_equal ["S256"], body["code_challenge_methods_supported"]
    assert_equal ["none"], body["token_endpoint_auth_methods_supported"]
    assert_equal ["read", "write"], body["scopes_supported"]
    assert_equal true, body["client_id_metadata_document_supported"]
    assert_equal true, body["authorization_response_iss_parameter_supported"]
    assert_not body.key?("registration_endpoint")
    assert_not_includes body["scopes_supported"], "offline_access"
    assert_cacheable
  end

  test "publishes the protected resource metadata for /mcp" do
    get oauth_protected_resource_path

    assert_response :success
    body = response.parsed_body
    assert_equal MCP_RESOURCE, body["resource"]
    assert_equal ["http://www.example.com"], body["authorization_servers"]
    assert_equal ["read", "write"], body["scopes_supported"]
    assert_equal ["header"], body["bearer_methods_supported"]
    assert_cacheable
  end

  private

  def assert_cacheable
    assert_match(/public/, response.headers["Cache-Control"])
    assert_match(/max-age=3600/, response.headers["Cache-Control"])
  end
end
